    ('d513d5d5-e95d-5b04-b628-b4a1970f42bb'::uuid, 'Nombres et calculs'),
    ('ae2a882f-7b8b-53bb-80bf-21b8b4812122'::uuid, 'Nombres et calculs'),
    ('ebf88cac-fd60-5a8a-aa2d-6da9a219314a'::uuid, 'Géométrie'),
    ('27b703e8-ce8e-5098-8991-6c9faf1c90cc'::uuid, 'Géométrie'),
    ('a6fc7a9d-dc23-5456-bb58-751dc2551f24'::uuid, 'Géométrie'),
    ('e2803fe6-baa3-5cc6-b2e1-54da7febc1cd'::uuid, 'Géométrie'),
    ('5731af00-4e7e-53c3-a955-cf8dc2e069c7'::uuid, 'Fonctions'),
