    ('54f77b25-79c6-57bc-90c1-7d1200863582'::uuid, 'Quiz — Trois formules à savoir dans les deux sens', 'Maths', '2de', 'Les identités remarquables', '8fbcb61c-d95c-5b47-ba09-a0ddeb8de278'::uuid),
    ('c65ae97c-4bae-5a33-a4d7-0991ad12cd4a'::uuid, 'Quiz — Résoudre sans perdre ni inventer de solutions', 'Maths', '2de', 'Les équations et inéquations', 'ad00c9d3-780b-50b2-9df8-754f595c410c'::uuid),
    ('6c15eb0a-aed7-5548-930e-f957559ed596'::uuid, 'Quiz — Le pied de la perpendiculaire, et la plus courte distance', 'Maths', '2de', 'Géométrie plane : triangles et projeté orthogonal d’un point sur une droite', '4f997f5c-e659-56c3-8f06-ee5519d6144b'::uuid),
