    ('155de1ea-a9c3-562f-9d1e-ab32027b9997'::uuid, 'Quiz — Reconnaître une droite à son équation', 'Maths', '2de', 'Équations de droites', '2a0804a5-3429-5c36-90da-362260a5fb00'::uuid),
    ('4cd0339e-3067-5a99-b9b0-ca86283637d1'::uuid, 'Quiz — Le vocabulaire qui sert toute l’année', 'Maths', '2de', 'Généralités sur les fonctions', '6a611198-24a5-5b29-a48a-827962460e3f'::uuid),
    ('323d129d-6976-589b-b375-5e1bd84cb695'::uuid, 'Quiz — La droite, et le taux d’accroissement constant', 'Maths', '2de', 'La fonction affine', '306981bf-e474-50e9-a87b-834e2b70876d'::uuid),
