    ('cae8560d-01d4-51fd-918e-ec88a1ad04a4'::uuid, 'Quiz — Croissante partout, et impaire', 'Maths', '2de', 'La fonction cube', '5a31fbf0-9eb0-59ec-a66a-15fc2bdf7589'::uuid),
    ('fac89da2-6bb3-5e98-869e-c883ea39ad1d'::uuid, 'Quiz — Définie seulement sur les positifs', 'Maths', '2de', 'La fonction racine carrée', '9587fb8d-ecbe-5c02-a43c-ca095be3e5d9'::uuid),
    ('4cc06f21-afa6-57cb-a56b-884e1bd7bbf8'::uuid, 'Quiz — L’hyperbole, et le trou en zéro', 'Maths', '2de', 'La fonction inverse', 'b66252be-474b-577e-8150-cfa6667091c0'::uuid),
    ('7031a9bb-ebec-5a08-91aa-63db54a8e272'::uuid, 'Quiz — Proportions, pourcentages et évolutions', 'Maths', '2de', 'Information chiffrée', '4dff04e2-1892-5b26-af7a-57c233c22f9d'::uuid),
    ('79e5fd94-f091-5010-b25a-6b65bf8b1813'::uuid, 'Quiz — Résumer une série sans la trahir', 'Maths', '2de', 'Statistique descriptive', 'c8a5c4a4-1728-5341-bb0a-76b8941d9b95'::uuid),
    ('fd5871b5-b6a9-5b07-bdb8-29174cbcf828'::uuid, 'Quiz — Modéliser le hasard', 'Maths', '2de', 'Probabilités : vocabulaire et outils', '88b0adeb-8586-5caa-8739-a8b849292565'::uuid),
    ('0a0d5e6c-e7b0-508f-a5fe-da8747be970d'::uuid, 'Quiz — Ce qu’un échantillon peut dire, et ce qu’il ne peut pas', 'Maths', '2de', 'Échantillonnage', '9f4f0740-ac99-5a4b-9d2f-eca302344dac'::uuid)
  ) AS v(id, title, subject, grade_level, chapter, lesson_id)
  JOIN public.lessons l ON l.id = v.lesson_id
 WHERE NOT EXISTS (SELECT 1 FROM public.quizzes qz WHERE qz.lesson_id = l.id)
ON CONFLICT (id) DO NOTHING;

-- 4. Questions -------------------------------------------------------------
INSERT INTO public.quiz_questions (id, quiz_id, question, kind, options, correct_index, explanation, position)
SELECT v.id, v.quiz_id, v.question, v.kind, v.options, v.correct_index, v.explanation, v.position
  FROM (VALUES
    ('9a4b3f60-16b3-58f8-90ba-73aab13e5be8'::uuid, '8e5ac9af-4ef0-5e3c-9c9e-45407d466868'::uuid, 'Quel ensemble contient tous les autres ?', 'mcq', '["ℝ, l’ensemble des réels","ℚ, l’ensemble des rationnels","ℤ, l’ensemble des entiers relatifs","ⅅ, l’ensemble des décimaux"]'::jsonb, 0, 'ℕ ⊂ ℤ ⊂ ⅅ ⊂ ℚ ⊂ ℝ.', 1),
    ('d76a0064-ed77-585f-b144-81dd8baa9baf'::uuid, '8e5ac9af-4ef0-5e3c-9c9e-45407d466868'::uuid, 'À quel ensemble le nombre √2 appartient-il ?', 'mcq', '["À ℝ mais pas à ℚ","À ℚ mais pas à ℝ","À ℤ","À ⅅ"]'::jsonb, 0, 'C’est un irrationnel : son écriture décimale est infinie et non périodique.', 2),
    ('3530288e-cd63-50d1-a469-07566ff40b43'::uuid, '8e5ac9af-4ef0-5e3c-9c9e-45407d466868'::uuid, 'Comment note-t-on l’ensemble des réels strictement compris entre 2 et 5 ?', 'mcq', '["]2 ; 5[","[2 ; 5]","[2 ; 5[","]2 ; 5]"]'::jsonb, 0, 'Les crochets ouverts excluent les bornes.', 3),
    ('f91958d6-6cb7-516d-b162-cb5f893a8d82'::uuid, '8e5ac9af-4ef0-5e3c-9c9e-45407d466868'::uuid, 'Comment écrit-on l’ensemble des réels inférieurs ou égaux à 3 ?', 'mcq', '["]−∞ ; 3]","[−∞ ; 3]","]−∞ ; 3[","[3 ; +∞["]'::jsonb, 0, 'Le crochet est toujours ouvert du côté de l’infini.', 4),
    ('e4a23999-d91a-5448-8a16-b2934e11dc60'::uuid, '8e5ac9af-4ef0-5e3c-9c9e-45407d466868'::uuid, 'Que vaut |−7| ?', 'mcq', '["7","−7","0","14"]'::jsonb, 0, 'La valeur absolue est la distance à zéro.', 5),
    ('6e435514-300b-5939-bbe9-dd004efb78eb'::uuid, '8e5ac9af-4ef0-5e3c-9c9e-45407d466868'::uuid, 'L’inéquation |x − 4| ≤ 2 se traduit par un intervalle centré en 4.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'C’est [2 ; 6], de centre 4 et de rayon 2.', 6),
    ('a7dbe1c8-0bb2-50c3-b73f-08817ec6ed24'::uuid, '8e5ac9af-4ef0-5e3c-9c9e-45407d466868'::uuid, 'Que donne l’intersection de [0 ; 5] et [3 ; 8] ?', 'mcq', '["[3 ; 5]","[0 ; 8]","[0 ; 3]","L’ensemble vide"]'::jsonb, 0, 'On garde ce qui appartient aux deux intervalles.', 7),
    ('abe0a531-119a-57a1-b53e-5643a9e42ac8'::uuid, '8e5ac9af-4ef0-5e3c-9c9e-45407d466868'::uuid, 'Le nombre 1/3 est-il un décimal ?', 'mcq', '["Non, mais il est rationnel","Oui","Non, il est irrationnel","Non, il est entier"]'::jsonb, 0, 'Son écriture décimale est infinie, mais c’est un quotient d’entiers.', 8),
    ('d99b39b0-5cd1-52c1-8452-719c1a89caca'::uuid, '8b551c6d-fdf8-51f5-9f87-037f2df8742d'::uuid, 'Qu’est-ce qu’un nombre décimal ?', 'mcq', '["Un nombre dont l’écriture décimale est finie","Un nombre à virgule","Un quotient de deux entiers","Un nombre inférieur à 1"]'::jsonb, 0, 'Il peut s’écrire a/10ⁿ avec a entier.', 1),
    ('5510a857-370f-5c47-9744-beeb69223745'::uuid, '8b551c6d-fdf8-51f5-9f87-037f2df8742d'::uuid, 'Comment reconnaît-on un rationnel à son écriture décimale ?', 'mcq', '["Elle est finie ou périodique","Elle est toujours infinie","Elle comporte moins de dix chiffres","Elle commence par zéro"]'::jsonb, 0, 'Réciproquement, tout développement périodique est rationnel.', 2),
    ('629d6333-d30c-5285-bf0d-bebfeff5bbeb'::uuid, '8b551c6d-fdf8-51f5-9f87-037f2df8742d'::uuid, 'Le nombre 0,142857142857… est-il rationnel ?', 'mcq', '["Oui, c’est 1/7","Non, il est irrationnel","Oui, c’est un décimal","Non, il n’est pas défini"]'::jsonb, 0, 'Son développement est périodique.', 3),
    ('eef47b73-046e-5efc-9765-77e51383a272'::uuid, '8b551c6d-fdf8-51f5-9f87-037f2df8742d'::uuid, 'Quelle est la nature de π ?', 'mcq', '["Irrationnel","Décimal","Rationnel","Entier"]'::jsonb, 0, 'Son écriture décimale est infinie et non périodique.', 4),
    ('591126d5-32bc-589b-851b-28d159bd065f'::uuid, '8b551c6d-fdf8-51f5-9f87-037f2df8742d'::uuid, 'Comment démontre-t-on que √2 est irrationnel ?', 'mcq', '["Par l’absurde, en supposant qu’il s’écrit p/q irréductible","Par récurrence","Par le calcul de ses décimales","Par une construction géométrique"]'::jsonb, 0, 'On aboutit à ce que p et q soient tous deux pairs.', 5),
    ('ba1c968a-8b27-574a-b9f1-90c654035bfe'::uuid, '8b551c6d-fdf8-51f5-9f87-037f2df8742d'::uuid, 'La fraction 3/8 correspond à un nombre décimal.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, '3/8 = 0,375 ; le dénominateur ne contient que le facteur 2.', 6),
    ('d9f7200f-49c8-53e1-8b6f-87a377adf40e'::uuid, '8b551c6d-fdf8-51f5-9f87-037f2df8742d'::uuid, 'Que vaut 2/3 + 1/6 ?', 'mcq', '["5/6","3/9","1/2","3/6"]'::jsonb, 0, 'On réduit au même dénominateur : 4/6 + 1/6.', 7),
    ('910adb86-0c74-5074-bdf6-33a6e6d26a48'::uuid, '8b551c6d-fdf8-51f5-9f87-037f2df8742d'::uuid, 'Pourquoi préférer une valeur exacte à une valeur approchée ?', 'mcq', '["Parce que les arrondis successifs s’accumulent en erreurs","Parce que c’est plus rapide à écrire","Parce que la calculatrice l’exige","Parce que les valeurs approchées sont interdites"]'::jsonb, 0, 'On n’arrondit qu’à la toute fin d’un calcul.', 8),
    ('b385992a-1ab5-5274-bb72-52eb9c54ad87'::uuid, '26639b1f-bb6b-597f-9c33-a0ce5bbe3025'::uuid, 'Qu’est-ce qu’un nombre premier ?', 'mcq', '["Un entier supérieur ou égal à 2 n’ayant que deux diviseurs positifs","Un nombre impair","Un nombre qui n’est pas décomposable","Le premier terme d’une suite"]'::jsonb, 0, '1 et lui-même.', 1),
    ('a30a7467-7970-5371-9cb3-6056fb7b97d8'::uuid, '26639b1f-bb6b-597f-9c33-a0ce5bbe3025'::uuid, 'Le nombre 1 est-il premier ?', 'mcq', '["Non, par convention, pour garantir l’unicité de la décomposition","Oui","Oui, c’est le plus petit","Cela dépend du contexte"]'::jsonb, 0, 'Sinon, tout produit pourrait être multiplié par 1 indéfiniment.', 2),
    ('e5b05fc7-f841-562b-8f3b-ce1a5c2d994a'::uuid, '26639b1f-bb6b-597f-9c33-a0ce5bbe3025'::uuid, 'Quel critère permet de savoir si un nombre est divisible par 3 ?', 'mcq', '["La somme de ses chiffres est divisible par 3","Il se termine par 3","Il est impair","Ses deux derniers chiffres sont divisibles par 3"]'::jsonb, 0, 'Même principe pour 9.', 3),
    ('eccfbb03-65e9-5d9e-9814-5bfd28c24ce2'::uuid, '26639b1f-bb6b-597f-9c33-a0ce5bbe3025'::uuid, 'Quelle est la décomposition en facteurs premiers de 360 ?', 'mcq', '["2³ × 3² × 5","2² × 3³ × 5","2 × 3 × 60","2⁴ × 3 × 5"]'::jsonb, 0, '8 × 9 × 5 = 360.', 4),
    ('0088dc42-b442-5f1c-935b-fd9bf91e297b'::uuid, '26639b1f-bb6b-597f-9c33-a0ce5bbe3025'::uuid, 'Jusqu’où faut-il tester les diviseurs pour savoir si n est premier ?', 'mcq', '["Jusqu’à √n","Jusqu’à n/2","Jusqu’à n","Jusqu’à 100"]'::jsonb, 0, 'Au-delà, on retrouverait des diviseurs déjà rencontrés.', 5),
    ('8bf99041-f2f0-5095-a050-425d2a9997b8'::uuid, '26639b1f-bb6b-597f-9c33-a0ce5bbe3025'::uuid, 'Il existe une infinité de nombres premiers.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Démontré par Euclide il y a plus de deux mille ans.', 6),
    ('4e5c12ee-cbc7-5bb1-b3e3-5843c11efa2c'::uuid, '26639b1f-bb6b-597f-9c33-a0ce5bbe3025'::uuid, 'Que signifie que 7 divise 91 ?', 'mcq', '["Il existe un entier k tel que 91 = 7 × k","91 est premier","7 est un multiple de 91","91/7 n’est pas entier"]'::jsonb, 0, 'Ici k = 13.', 7),
    ('98ffea0f-f675-5a70-9002-1299dc603dd7'::uuid, '26639b1f-bb6b-597f-9c33-a0ce5bbe3025'::uuid, 'Sur quoi repose la sécurité de nombreux systèmes de chiffrement ?', 'mcq', '["La difficulté de factoriser un très grand nombre","La rareté des nombres pairs","Le calcul du PGCD","Les critères de divisibilité"]'::jsonb, 0, 'Multiplier est facile, factoriser ne l’est pas.', 8),
    ('1500c87e-39d1-506e-a614-d93f64bf83d4'::uuid, '0626bf74-b771-596b-8393-1943147edbd7'::uuid, 'Que vaut a⁵ × a³ ?', 'mcq', '["a⁸","a¹⁵","a²","2a⁸"]'::jsonb, 0, 'On additionne les exposants.', 1),
    ('2cc8bbe8-66ac-50dc-bca7-5ee3d59a3d12'::uuid, '0626bf74-b771-596b-8393-1943147edbd7'::uuid, 'Que vaut (a³)⁴ ?', 'mcq', '["a¹²","a⁷","a⁸¹","4a³"]'::jsonb, 0, 'On multiplie les exposants.', 2),
    ('6ea556e6-ecb7-5283-91bd-629cf8cd616d'::uuid, '0626bf74-b771-596b-8393-1943147edbd7'::uuid, 'Que vaut a⁻³ ?', 'mcq', '["1/a³","−a³","0","3/a"]'::jsonb, 0, 'Un exposant négatif donne l’inverse.', 3),
    ('ff352a33-8351-5ea3-a61e-ef244a5ee3b5'::uuid, '0626bf74-b771-596b-8393-1943147edbd7'::uuid, '√9 + √16 est-il égal à √25 ?', 'mcq', '["Non : 3 + 4 = 7, alors que √25 = 5","Oui","Oui, si a et b sont positifs","Cela dépend"]'::jsonb, 0, 'La racine d’une somme n’est pas la somme des racines.', 4),
    ('3a6fdf2b-a303-5e24-a99c-508292ae9751'::uuid, '0626bf74-b771-596b-8393-1943147edbd7'::uuid, 'Que vaut √(a²) ?', 'mcq', '["|a|","a","a²","−a"]'::jsonb, 0, 'La racine carrée est toujours positive.', 5),
    ('f9f19ace-8712-56d4-9adf-13921e7e3502'::uuid, '0626bf74-b771-596b-8393-1943147edbd7'::uuid, 'La notation scientifique écrit un nombre sous la forme a × 10ⁿ avec 1 ≤ |a| < 10.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Elle facilite la comparaison des ordres de grandeur.', 6),
    ('12b618ed-9e76-56ca-91dd-8e92bd159e58'::uuid, '0626bf74-b771-596b-8393-1943147edbd7'::uuid, 'Peut-on simplifier (x + 3)/(x + 5) en 3/5 ?', 'mcq', '["Non, on ne simplifie que des facteurs, jamais des termes","Oui","Oui, si x est positif","Oui, si x est différent de −5"]'::jsonb, 0, 'C’est l’erreur la plus fréquente du calcul littéral.', 7),
    ('6d989754-78cb-5b00-ade5-e2fbc64ee649'::uuid, '0626bf74-b771-596b-8393-1943147edbd7'::uuid, 'Comment rendre rationnel le dénominateur de 1/√3 ?', 'mcq', '["En multipliant numérateur et dénominateur par √3","En élevant au carré","En prenant la racine du numérateur","C’est impossible"]'::jsonb, 0, 'On obtient √3/3.', 8),
    ('283e92d5-7a3c-517d-ad01-501fbafadb80'::uuid, '54f77b25-79c6-57bc-90c1-7d1200863582'::uuid, 'Que vaut (a + b)² ?', 'mcq', '["a² + 2ab + b²","a² + b²","a² − 2ab + b²","2a + 2b"]'::jsonb, 0, 'Le double produit est le terme qu’on oublie.', 1),
    ('4a7876cd-1981-57c0-b00d-423dd6e5078e'::uuid, '54f77b25-79c6-57bc-90c1-7d1200863582'::uuid, 'Que vaut (a + b)(a − b) ?', 'mcq', '["a² − b²","a² + b²","a² − 2ab + b²","(a − b)²"]'::jsonb, 0, 'La différence de deux carrés.', 2),
    ('2c57f9cc-4267-5546-8861-19c59de0fff8'::uuid, '54f77b25-79c6-57bc-90c1-7d1200863582'::uuid, 'Comment factoriser x² − 49 ?', 'mcq', '["(x − 7)(x + 7)","(x − 7)²","(x + 7)²","x(x − 49)"]'::jsonb, 0, 'Différence de deux carrés, avec b = 7.', 3),
    ('01197320-6756-57fd-8f40-e9218f951881'::uuid, '54f77b25-79c6-57bc-90c1-7d1200863582'::uuid, 'Comment factoriser x² + 10x + 25 ?', 'mcq', '["(x + 5)²","(x − 5)²","(x + 5)(x − 5)","x(x + 10) + 25"]'::jsonb, 0, 'On reconnaît a = x, b = 5 et le double produit 10x.', 4),
    ('048bbb73-5188-5256-a6dd-72c561c841f3'::uuid, '54f77b25-79c6-57bc-90c1-7d1200863582'::uuid, 'Développez (3x − 2)².', 'mcq', '["9x² − 12x + 4","9x² + 12x + 4","9x² − 4","3x² − 12x + 4"]'::jsonb, 0, 'Le double produit vaut 2 × 3x × 2 = 12x.', 5),
    ('6f3b3c20-ca6c-5881-ada8-544883f1603a'::uuid, '54f77b25-79c6-57bc-90c1-7d1200863582'::uuid, 'Un produit de facteurs est nul si et seulement si l’un des facteurs est nul.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'C’est ce qui rend la forme factorisée si utile pour résoudre.', 6),
    ('e5db7503-29d7-5df3-b7c5-9a6cf902b784'::uuid, '54f77b25-79c6-57bc-90c1-7d1200863582'::uuid, 'Que vaut 101 × 99 en utilisant une identité remarquable ?', 'mcq', '["9 999","9 990","10 001","9 899"]'::jsonb, 0, '(100 + 1)(100 − 1) = 10 000 − 1.', 7),
    ('dc1cdca2-bec8-5a25-a661-f2d73978c623'::uuid, '54f77b25-79c6-57bc-90c1-7d1200863582'::uuid, 'Quelle forme faut-il obtenir pour résoudre facilement une équation ?', 'mcq', '["La forme factorisée","La forme développée","La forme canonique","La forme décimale"]'::jsonb, 0, 'On applique ensuite le principe du produit nul.', 8),
    ('c5b9baa8-f1da-50ca-9f7b-9ecbe86ab948'::uuid, 'c65ae97c-4bae-5a33-a4d7-0991ad12cd4a'::uuid, 'Quelle est la solution de 3x − 12 = 0 ?', 'mcq', '["x = 4","x = −4","x = 12","x = 36"]'::jsonb, 0, 'On isole x puis on divise par 3.', 1),
    ('1d023ccd-2ad3-54af-a6a6-916b41349d38'::uuid, 'c65ae97c-4bae-5a33-a4d7-0991ad12cd4a'::uuid, 'Quelles sont les solutions de (x − 2)(x + 5) = 0 ?', 'mcq', '["2 et −5","−2 et 5","2 et 5","−2 et −5"]'::jsonb, 0, 'Un produit est nul si l’un des facteurs est nul.', 2),
    ('8e8c3917-a0cb-59b5-9934-4c0e59e6a6fc'::uuid, 'c65ae97c-4bae-5a33-a4d7-0991ad12cd4a'::uuid, 'Que faut-il déterminer avant de résoudre une équation quotient ?', 'mcq', '["Les valeurs interdites, qui annulent le dénominateur","Le signe du numérateur","Le degré de l’équation","La forme canonique"]'::jsonb, 0, 'Sans elles, on risque de proposer une solution non définie.', 3),
    ('734b3289-4d02-502b-8470-5ae06e88ea02'::uuid, 'c65ae97c-4bae-5a33-a4d7-0991ad12cd4a'::uuid, 'Que devient l’inégalité quand on divise les deux membres par −2 ?', 'mcq', '["Elle change de sens","Elle reste identique","Elle devient une égalité","Elle n’a plus de solution"]'::jsonb, 0, 'C’est la règle propre aux inéquations.', 4),
    ('9aaeec51-ce06-54f1-85cb-f489a1d21a47'::uuid, 'c65ae97c-4bae-5a33-a4d7-0991ad12cd4a'::uuid, 'Résolvez −2x + 6 > 0.', 'mcq', '["x < 3","x > 3","x < −3","x > −3"]'::jsonb, 0, 'On divise par −2 en inversant le sens.', 5),
    ('70ac9a2b-d452-5afc-9b08-2539de6fe070'::uuid, 'c65ae97c-4bae-5a33-a4d7-0991ad12cd4a'::uuid, 'Un quotient est nul lorsque son numérateur est nul et son dénominateur non nul.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Les deux conditions sont nécessaires.', 6),
    ('6f1aaea9-15db-568b-822a-b688be630ea1'::uuid, 'c65ae97c-4bae-5a33-a4d7-0991ad12cd4a'::uuid, 'Quel outil sert à résoudre une inéquation produit ?', 'mcq', '["Le tableau de signes","La forme canonique","Le discriminant","Le théorème de Thalès"]'::jsonb, 0, 'On étudie le signe de chaque facteur puis on applique la règle des signes.', 7),
    ('ea0e796f-fd38-503a-bd70-16937ee31380'::uuid, 'c65ae97c-4bae-5a33-a4d7-0991ad12cd4a'::uuid, 'Comment s’écrit l’ensemble des solutions d’une inéquation ?', 'mcq', '["Sous forme d’intervalle","Sous forme de fraction","Sous forme d’équation","Sous forme de tableau uniquement"]'::jsonb, 0, 'Par exemple S = ]−∞ ; 3].', 8),
    ('567edf1b-d6c8-5566-a22d-6a2244c69846'::uuid, '6c15eb0a-aed7-5548-930e-f957559ed596'::uuid, 'Qu’est-ce que le projeté orthogonal d’un point M sur une droite d ?', 'mcq', '["Le point H de d tel que (MH) soit perpendiculaire à d","Le milieu du segment reliant M à d","Le point de d le plus éloigné de M","L’intersection de d avec la médiatrice"]'::jsonb, 0, 'Il est unique.', 1),
    ('c768e5c2-d410-53a3-ac78-68193f794fcd'::uuid, '6c15eb0a-aed7-5548-930e-f957559ed596'::uuid, 'Que représente la distance MH lorsque H est le projeté orthogonal de M sur d ?', 'mcq', '["La plus courte distance de M à la droite d","La distance moyenne","Le rayon du cercle circonscrit","La longueur de la médiane"]'::jsonb, 0, 'Toute autre distance de M à un point de d est plus grande.', 2),
    ('0fae776a-3655-51ed-b341-f226ad462c20'::uuid, '6c15eb0a-aed7-5548-930e-f957559ed596'::uuid, 'Où se coupent les médiatrices d’un triangle ?', 'mcq', '["Au centre du cercle circonscrit","À l’orthocentre","Au centre de gravité","Au centre du cercle inscrit"]'::jsonb, 0, 'Elles sont équidistantes des trois sommets.', 3),
    ('7d5322a3-4d9f-56e7-bcc6-d946bdc5638d'::uuid, '6c15eb0a-aed7-5548-930e-f957559ed596'::uuid, 'Où se coupent les hauteurs d’un triangle ?', 'mcq', '["À l’orthocentre","Au centre de gravité","Au centre du cercle inscrit","Au centre du cercle circonscrit"]'::jsonb, 0, 'Chaque hauteur passe par un sommet perpendiculairement au côté opposé.', 4),
    ('60c57e86-06e8-5248-9d81-55774e567c7d'::uuid, '6c15eb0a-aed7-5548-930e-f957559ed596'::uuid, 'Où se situe le centre de gravité sur une médiane ?', 'mcq', '["Aux deux tiers depuis le sommet","Au milieu","Au tiers depuis le sommet","Au pied de la médiane"]'::jsonb, 0, 'Propriété classique du point de concours des médianes.', 5),
    ('bb31e7fc-4292-50df-9acb-ec6a2b25c05a'::uuid, '6c15eb0a-aed7-5548-930e-f957559ed596'::uuid, 'Le cosinus d’un angle aigu dans un triangle rectangle est le rapport du côté adjacent à l’hypoténuse.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Le sinus utilise le côté opposé.', 6),
    ('9dd07851-99f1-5926-b2a3-fcfd44771367'::uuid, '6c15eb0a-aed7-5548-930e-f957559ed596'::uuid, 'Que permet la réciproque du théorème de Pythagore ?', 'mcq', '["Démontrer qu’un triangle est rectangle","Calculer une hauteur","Calculer une aire","Démontrer que deux droites sont parallèles"]'::jsonb, 0, 'On compare le carré du plus grand côté à la somme des deux autres.', 7),
    ('8a7f4632-88e3-587a-8ec4-4845c720cde7'::uuid, '6c15eb0a-aed7-5548-930e-f957559ed596'::uuid, 'Que permet le théorème de Thalès ?', 'mcq', '["Calculer des longueurs dans une configuration de droites parallèles","Démontrer qu’un triangle est rectangle","Trouver un projeté orthogonal","Calculer un angle"]'::jsonb, 0, 'Sa réciproque sert à prouver un parallélisme.', 8),
    ('d17be445-e96d-51bd-9f0b-97ce43a525aa'::uuid, '8704909d-c3e7-59d7-ab46-4218443250b7'::uuid, 'Quelles sont les trois caractéristiques d’un vecteur ?', 'mcq', '["Direction, sens et norme","Origine, extrémité et longueur","Abscisse, ordonnée et angle","Position, vitesse et sens"]'::jsonb, 0, 'Un vecteur n’a pas de position fixe.', 1),
    ('7d828512-df60-5fa2-95d9-104b85398b33'::uuid, '8704909d-c3e7-59d7-ab46-4218443250b7'::uuid, 'Que signifie l’égalité des vecteurs AB et CD ?', 'mcq', '["ABDC est un parallélogramme","ABCD est un parallélogramme","Les points sont alignés","AB et CD ont même longueur seulement"]'::jsonb, 0, 'Attention à l’ordre des sommets.', 2),
    ('b9d41d08-5613-5e23-b59f-87579b01e63f'::uuid, '8704909d-c3e7-59d7-ab46-4218443250b7'::uuid, 'Qu’énonce la relation de Chasles ?', 'mcq', '["AB + BC = AC","AB + BC = CA","AB − BC = AC","AB × BC = AC"]'::jsonb, 0, 'Enchaîner deux déplacements revient à en faire un seul.', 3),
    ('8d86a48e-3836-56ff-b08c-ddfa8f2d51ba'::uuid, '8704909d-c3e7-59d7-ab46-4218443250b7'::uuid, 'Que vaut la somme des vecteurs AB et BA ?', 'mcq', '["Le vecteur nul","Le vecteur AA de norme 1","2 fois le vecteur AB","Le vecteur AB"]'::jsonb, 0, 'On revient au point de départ.', 4),
    ('adaccaf3-1a82-5d81-964d-e0e6bcb93a83'::uuid, '8704909d-c3e7-59d7-ab46-4218443250b7'::uuid, 'Quel est le sens du vecteur −3u par rapport à u ?', 'mcq', '["Sens opposé, avec une norme trois fois plus grande","Même sens, norme trois fois plus grande","Sens opposé, norme trois fois plus petite","Même sens, norme identique"]'::jsonb, 0, 'Le signe donne le sens, la valeur absolue la norme.', 5),
    ('e7204a60-5b55-5500-b62d-aeb4352938da'::uuid, '8704909d-c3e7-59d7-ab46-4218443250b7'::uuid, 'Deux vecteurs non nuls sont colinéaires s’il existe un réel k tel que l’un soit égal à k fois l’autre.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'La colinéarité traduit le parallélisme des directions.', 6),
    ('a7ea646a-9277-5a2d-941d-04025a0a0fb9'::uuid, '8704909d-c3e7-59d7-ab46-4218443250b7'::uuid, 'Un même vecteur peut-il être représenté à partir de plusieurs points ?', 'mcq', '["Oui, il décrit un déplacement, pas une position","Non, il est lié à son origine","Oui, seulement dans un repère","Non, sauf s’il est nul"]'::jsonb, 0, 'D’où l’intérêt de la notion de vecteur égal.', 7),
    ('b37c93ab-46d5-5f03-8e1c-c6206b0153ac'::uuid, '8704909d-c3e7-59d7-ab46-4218443250b7'::uuid, 'Comment démontre-t-on que trois points A, B et C sont alignés à l’aide de vecteurs ?', 'mcq', '["En montrant que AB et AC sont colinéaires","En montrant que AB = AC","En calculant la norme de BC","En vérifiant que AB + AC = 0"]'::jsonb, 0, 'Ils partagent le point A, donc la colinéarité donne l’alignement.', 8),
    ('b11c26a3-0675-50b2-9965-09d8f8a131e6'::uuid, '3f76c3ad-797c-535c-9678-b264ce0edc43'::uuid, 'Quelles sont les coordonnées du vecteur AB si A(1 ; 2) et B(4 ; 7) ?', 'mcq', '["(3 ; 5)","(5 ; 9)","(−3 ; −5)","(4 ; 14)"]'::jsonb, 0, 'On soustrait l’origine à l’extrémité.', 1),
    ('46ce7f27-a38a-52b8-966a-1255fcb9d336'::uuid, '3f76c3ad-797c-535c-9678-b264ce0edc43'::uuid, 'Quelles sont les coordonnées du milieu de [AB] avec A(1 ; 2) et B(5 ; 8) ?', 'mcq', '["(3 ; 5)","(4 ; 6)","(2 ; 3)","(6 ; 10)"]'::jsonb, 0, 'On fait la moyenne des abscisses et des ordonnées.', 2),
    ('4dbd747f-aa55-5939-b8b8-f379dd1debf3'::uuid, '3f76c3ad-797c-535c-9678-b264ce0edc43'::uuid, 'Dans quel type de repère la formule de distance est-elle valable ?', 'mcq', '["Un repère orthonormé","N’importe quel repère","Un repère orthogonal seulement","Un repère gradué"]'::jsonb, 0, 'Elle repose sur le théorème de Pythagore.', 3),
    ('1a9920e6-50da-5860-9250-7d8d07be04dc'::uuid, '3f76c3ad-797c-535c-9678-b264ce0edc43'::uuid, 'Quelle est la distance AB pour A(0 ; 0) et B(3 ; 4) en repère orthonormé ?', 'mcq', '["5","7","25","√7"]'::jsonb, 0, '√(9 + 16) = √25.', 4),
    ('ff6d997d-332f-5011-9ff7-c96fb95be7ad'::uuid, '3f76c3ad-797c-535c-9678-b264ce0edc43'::uuid, 'Quel critère caractérise la colinéarité de u(x ; y) et v(x’ ; y’) ?', 'mcq', '["xy’ − yx’ = 0","xx’ + yy’ = 0","x + y = x’ + y’","xy = x’y’"]'::jsonb, 0, 'C’est le déterminant des deux vecteurs.', 5),
    ('68da967b-f68d-5b7f-987a-890e21576765'::uuid, '3f76c3ad-797c-535c-9678-b264ce0edc43'::uuid, 'Pour additionner deux vecteurs, on additionne leurs coordonnées.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'De même, multiplier par k multiplie chaque coordonnée.', 6),
    ('9bb094e8-2ced-5ab1-8b01-369795144ba8'::uuid, '3f76c3ad-797c-535c-9678-b264ce0edc43'::uuid, 'Comment démontrer qu’un quadrilatère ABDC est un parallélogramme avec des coordonnées ?', 'mcq', '["En montrant que les vecteurs AB et CD sont égaux","En calculant les quatre longueurs","En vérifiant que les angles sont droits","En calculant l’aire"]'::jsonb, 0, 'Ou en vérifiant que les diagonales ont le même milieu.', 7),
    ('f9bbcb07-efc0-5cda-a1af-177c991c9967'::uuid, '3f76c3ad-797c-535c-9678-b264ce0edc43'::uuid, 'Les vecteurs u(2 ; 6) et v(1 ; 3) sont-ils colinéaires ?', 'mcq', '["Oui, car 2 × 3 − 6 × 1 = 0","Non","Oui, car leurs normes sont égales","On ne peut pas le savoir"]'::jsonb, 0, 'u est le double de v.', 8),
    ('bc8dcc41-55f3-5061-8b54-dc58ebf0d22d'::uuid, '155de1ea-a9c3-562f-9d1e-ab32027b9997'::uuid, 'Que représente m dans l’équation y = mx + p ?', 'mcq', '["Le coefficient directeur","L’ordonnée à l’origine","L’abscisse à l’origine","La pente du vecteur normal"]'::jsonb, 0, 'Il mesure la variation de y quand x augmente de 1.', 1),
    ('bb41156a-3bf5-529e-952d-7c21849417bc'::uuid, '155de1ea-a9c3-562f-9d1e-ab32027b9997'::uuid, 'Quelle est l’équation d’une droite parallèle à l’axe des ordonnées ?', 'mcq', '["x = c","y = c","y = mx","y = x + c"]'::jsonb, 0, 'Elle n’admet pas d’équation réduite.', 2),
    ('5e8889a7-6aa7-57a4-87b4-2fe7cb378383'::uuid, '155de1ea-a9c3-562f-9d1e-ab32027b9997'::uuid, 'Comment calcule-t-on le coefficient directeur passant par A(1 ; 2) et B(3 ; 8) ?', 'mcq', '["(8 − 2)/(3 − 1) = 3","(3 − 1)/(8 − 2)","8/3","(8 + 2)/(3 + 1)"]'::jsonb, 0, 'Variation des ordonnées sur variation des abscisses.', 3),
    ('c29738b6-b0eb-5c43-b5b6-4fad8fab1898'::uuid, '155de1ea-a9c3-562f-9d1e-ab32027b9997'::uuid, 'Quel est un vecteur directeur de la droite d’équation 2x + 3y − 6 = 0 ?', 'mcq', '["(−3 ; 2)","(2 ; 3)","(3 ; 2)","(6 ; 0)"]'::jsonb, 0, 'Pour ax + by + c = 0, le vecteur (−b ; a) convient.', 4),
    ('50a74698-b790-5e78-acca-6bc1db9c26e2'::uuid, '155de1ea-a9c3-562f-9d1e-ab32027b9997'::uuid, 'Deux droites de coefficients directeurs égaux sont parallèles.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Confondues si elles ont aussi la même ordonnée à l’origine.', 5),
    ('c2d13219-ff24-5d39-b330-3e451b080bd8'::uuid, '155de1ea-a9c3-562f-9d1e-ab32027b9997'::uuid, 'Comment trouver le point d’intersection de deux droites sécantes ?', 'mcq', '["En résolvant le système formé par leurs deux équations","En comparant leurs coefficients directeurs","En calculant la moyenne de leurs ordonnées à l’origine","En traçant leur médiatrice"]'::jsonb, 0, 'Le couple solution donne les coordonnées du point.', 6),
    ('668919c3-e07a-54ec-b04a-fe3dabd0db87'::uuid, '155de1ea-a9c3-562f-9d1e-ab32027b9997'::uuid, 'Que signifie p dans l’équation y = mx + p ?', 'mcq', '["L’ordonnée du point d’intersection avec l’axe des ordonnées","La pente","L’abscisse à l’origine","La distance à l’origine"]'::jsonb, 0, 'C’est la valeur de y quand x vaut 0.', 7),
    ('dafb0737-2205-5f44-9be1-37d76cf63d2c'::uuid, '155de1ea-a9c3-562f-9d1e-ab32027b9997'::uuid, 'Une droite de coefficient directeur négatif est décroissante.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Quand x augmente, y diminue.', 8),
    ('44447cf2-b9e4-5293-b0fc-586d9d54cfcf'::uuid, '4cd0339e-3067-5a99-b9b0-ca86283637d1'::uuid, 'Qu’est-ce qu’une fonction ?', 'mcq', '["Un procédé qui associe à chaque nombre au plus une image","Une courbe du plan","Une équation à deux inconnues","Une suite de nombres"]'::jsonb, 0, 'Un antécédent a une image unique.', 1),
    ('67576cba-30f0-59e1-93a3-74b02f5d74c0'::uuid, '4cd0339e-3067-5a99-b9b0-ca86283637d1'::uuid, 'Qu’est-ce que l’ensemble de définition ?', 'mcq', '["L’ensemble des valeurs de x pour lesquelles f(x) existe","L’ensemble des images","L’ensemble des solutions","L’intervalle d’étude choisi"]'::jsonb, 0, 'On exclut les valeurs interdites.', 2),
    ('bf00d9ca-9060-59e5-aec7-bbb83f13ebfa'::uuid, '4cd0339e-3067-5a99-b9b0-ca86283637d1'::uuid, 'Si f(3) = 7, que peut-on dire ?', 'mcq', '["7 est l’image de 3, et 3 un antécédent de 7","3 est l’image de 7","7 est la solution de f","3 et 7 sont des antécédents"]'::jsonb, 0, 'L’ordre du vocabulaire compte.', 3),
    ('b355ad24-7cf5-59a0-829b-bf1fa3fdf6e6'::uuid, '4cd0339e-3067-5a99-b9b0-ca86283637d1'::uuid, 'Un nombre peut-il avoir plusieurs antécédents ?', 'mcq', '["Oui","Non, jamais","Oui, seulement si la fonction est affine","Non, sauf pour la fonction carré"]'::jsonb, 0, 'En revanche il n’a qu’une seule image.', 4),
    ('1ce096eb-94eb-5a31-8a11-2de7e90f14a7'::uuid, '4cd0339e-3067-5a99-b9b0-ca86283637d1'::uuid, 'Que signifie que f est croissante sur un intervalle ?', 'mcq', '["Si a ≤ b alors f(a) ≤ f(b)","Si a ≤ b alors f(a) ≥ f(b)","f(x) est toujours positive","La courbe est au-dessus de l’axe"]'::jsonb, 0, 'Elle conserve l’ordre.', 5),
    ('8f8809c7-f861-56ae-bfcf-8d524045f1c8'::uuid, '4cd0339e-3067-5a99-b9b0-ca86283637d1'::uuid, 'Une courbe coupée deux fois par une même verticale peut représenter une fonction.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Ce serait donner deux images au même nombre.', 6),
    ('3cbd955a-917c-595d-8083-f43013331f94'::uuid, '4cd0339e-3067-5a99-b9b0-ca86283637d1'::uuid, 'Comment résout-on graphiquement f(x) = 3 ?', 'mcq', '["On cherche les abscisses des points de la courbe d’ordonnée 3","On cherche l’image de 3","On regarde où la courbe coupe l’axe des abscisses","On calcule le maximum"]'::jsonb, 0, 'On coupe la courbe par la droite y = 3.', 7),
    ('3f83228a-07ac-50e4-957d-794d31799d50'::uuid, '4cd0339e-3067-5a99-b9b0-ca86283637d1'::uuid, 'Que lit-on dans un tableau de signes de f ?', 'mcq', '["Où la courbe est au-dessus ou au-dessous de l’axe des abscisses","Les variations de f","Les extremums","L’ensemble de définition"]'::jsonb, 0, 'Le tableau de variations, lui, donne le sens de variation.', 8),
    ('200fe26e-c1db-5e42-afc4-ee561e951ee3'::uuid, '323d129d-6976-589b-b375-5e1bd84cb695'::uuid, 'Quelle est la forme d’une fonction affine ?', 'mcq', '["f(x) = ax + b","f(x) = ax²","f(x) = a/x","f(x) = √x"]'::jsonb, 0, 'Sa courbe est une droite.', 1),
    ('92e5c492-2687-55e6-ad44-1c12310e8cd6'::uuid, '323d129d-6976-589b-b375-5e1bd84cb695'::uuid, 'Quand une fonction affine est-elle croissante ?', 'mcq', '["Lorsque a > 0","Lorsque b > 0","Lorsque a < 0","Lorsque a = 0"]'::jsonb, 0, 'Le signe de a donne le sens de variation.', 2),
    ('5e569176-9b14-5f4e-83fb-1c6c5517ddd0'::uuid, '323d129d-6976-589b-b375-5e1bd84cb695'::uuid, 'Qu’est-ce qu’une fonction linéaire ?', 'mcq', '["Une fonction affine avec b = 0","Une fonction affine avec a = 0","Une fonction constante","Une fonction du second degré"]'::jsonb, 0, 'Sa droite passe par l’origine : c’est une proportionnalité.', 3),
    ('7aa0b0a8-c5b0-579d-acc2-7a7c28cf8501'::uuid, '323d129d-6976-589b-b375-5e1bd84cb695'::uuid, 'Que vaut le taux d’accroissement d’une fonction affine ?', 'mcq', '["Il est constant et égal à a","Il varie selon les points choisis","Il vaut b","Il vaut a + b"]'::jsonb, 0, 'C’est la propriété caractéristique des fonctions affines.', 4),
    ('fb2567e9-9ce0-5354-8e37-d090835acfb3'::uuid, '323d129d-6976-589b-b375-5e1bd84cb695'::uuid, 'Pour quelle valeur f(x) = 2x − 6 s’annule-t-elle ?', 'mcq', '["x = 3","x = −3","x = 6","x = −6"]'::jsonb, 0, 'On résout 2x − 6 = 0.', 5),
    ('97b7a4d3-7cc6-5c3b-8b4d-810642226aea'::uuid, '323d129d-6976-589b-b375-5e1bd84cb695'::uuid, 'Une fonction affine avec a = 0 est constante.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Sa courbe est une droite horizontale.', 6),
    ('935aef55-7ec6-56a0-b277-3ec14d69b9fd'::uuid, '323d129d-6976-589b-b375-5e1bd84cb695'::uuid, 'Combien de points suffisent à tracer la droite d’une fonction affine ?', 'mcq', '["Deux","Un","Trois","Quatre"]'::jsonb, 0, 'Deux points distincts déterminent une droite.', 7),
    ('62b7658a-f937-54ac-b517-3d02c6828027'::uuid, '323d129d-6976-589b-b375-5e1bd84cb695'::uuid, 'Quel est le signe de f(x) = −2x + 4 pour x > 2 ?', 'mcq', '["Négatif","Positif","Nul","Variable"]'::jsonb, 0, 'a est négatif : f est positive avant 2 et négative après.', 8),
    ('58593e62-e9f2-56a3-b9dd-00eba0231676'::uuid, '2e3a82c6-e54c-5cd7-9c57-1051c3d17ecc'::uuid, 'Sur quel intervalle la fonction carré est-elle décroissante ?', 'mcq', '["]−∞ ; 0]","[0 ; +∞[","ℝ tout entier","Elle est toujours croissante"]'::jsonb, 0, 'Elle atteint son minimum en 0.', 1),
    ('0c3453ad-fbef-52a1-ac16-607dd3ce9bbc'::uuid, '2e3a82c6-e54c-5cd7-9c57-1051c3d17ecc'::uuid, 'Quel est le minimum de la fonction carré ?', 'mcq', '["0, atteint en x = 0","1, atteint en x = 1","Elle n’a pas de minimum","−1, atteint en x = 0"]'::jsonb, 0, 'Un carré n’est jamais négatif.', 2),
    ('70ae7703-ccde-505b-830b-9bb85c987849'::uuid, '2e3a82c6-e54c-5cd7-9c57-1051c3d17ecc'::uuid, 'Comment s’appelle la courbe de la fonction carré ?', 'mcq', '["Une parabole","Une hyperbole","Une droite","Un cercle"]'::jsonb, 0, 'De sommet l’origine du repère.', 3),
    ('c43f5f9d-7554-5ad5-9366-f5e182f149d8'::uuid, '2e3a82c6-e54c-5cd7-9c57-1051c3d17ecc'::uuid, 'La fonction carré est paire. Que signifie cette propriété ?', 'mcq', '["Sa courbe est symétrique par rapport à l’axe des ordonnées","Elle ne prend que des valeurs paires","Elle est croissante","Elle passe par l’origine"]'::jsonb, 0, 'Parce que (−x)² = x².', 4),
    ('a3bb7acf-7806-5562-a0f7-5f082d2a6a8b'::uuid, '2e3a82c6-e54c-5cd7-9c57-1051c3d17ecc'::uuid, 'Combien de solutions a l’équation x² = 16 ?', 'mcq', '["Deux : 4 et −4","Une : 4","Aucune","Une infinité"]'::jsonb, 0, 'Oublier la solution négative est une faute classique.', 5),
    ('f91ceb67-dd94-520a-858a-9bdf0467ade7'::uuid, '2e3a82c6-e54c-5cd7-9c57-1051c3d17ecc'::uuid, 'L’équation x² = −4 admet des solutions réelles.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Un carré est toujours positif ou nul.', 6),
    ('913ac0f0-8d1f-57f1-9aaa-c32c923b6ff5'::uuid, '2e3a82c6-e54c-5cd7-9c57-1051c3d17ecc'::uuid, 'Quelle est la solution de x² ≤ 9 ?', 'mcq', '["[−3 ; 3]","]−∞ ; 3]","[3 ; +∞[","[0 ; 3]"]'::jsonb, 0, 'La parabole est sous la droite y = 9 entre −3 et 3.', 7),
    ('1dc435a1-c33b-5a18-aa70-9593f6e12649'::uuid, '2e3a82c6-e54c-5cd7-9c57-1051c3d17ecc'::uuid, 'Peut-on déduire de a < b que a² < b² ?', 'mcq', '["Non, cela dépend des signes de a et b","Oui, toujours","Oui, si a et b sont non nuls","Non, jamais"]'::jsonb, 0, 'La fonction carré ne conserve pas l’ordre sur ℝ.', 8),
    ('5e25fb56-5a81-5327-9c0d-1bffe484f37f'::uuid, 'cae8560d-01d4-51fd-918e-ec88a1ad04a4'::uuid, 'Sur quel intervalle la fonction cube est-elle croissante ?', 'mcq', '["Sur ℝ tout entier","Sur [0 ; +∞[ seulement","Sur ]−∞ ; 0] seulement","Elle n’est jamais croissante"]'::jsonb, 0, 'Elle conserve l’ordre partout.', 1),
    ('a65631d2-f86a-5090-8909-87727acb9c64'::uuid, 'cae8560d-01d4-51fd-918e-ec88a1ad04a4'::uuid, 'La fonction cube est impaire. Quelle en est la conséquence graphique ?', 'mcq', '["Sa courbe est symétrique par rapport à l’origine","Sa courbe est symétrique par rapport à l’axe des ordonnées","Sa courbe est une droite","Sa courbe est croissante puis décroissante"]'::jsonb, 0, 'Parce que (−x)³ = −x³.', 2),
    ('13928a26-eb1e-51d7-80f8-1bae9d830fb4'::uuid, 'cae8560d-01d4-51fd-918e-ec88a1ad04a4'::uuid, 'Combien de solutions a l’équation x³ = −27 ?', 'mcq', '["Une : −3","Aucune","Deux : 3 et −3","Une infinité"]'::jsonb, 0, 'Le cube conserve le signe.', 3),
    ('2d08f47e-d06b-508e-87b0-8029fd7be390'::uuid, 'cae8560d-01d4-51fd-918e-ec88a1ad04a4'::uuid, 'Quel est le signe de x³ ?', 'mcq', '["Celui de x","Toujours positif","Toujours négatif","Positif si x est pair"]'::jsonb, 0, 'Négatif avant 0, positif après.', 4),
    ('0dca0634-fe3b-548f-96a7-71e008c9ec79'::uuid, 'cae8560d-01d4-51fd-918e-ec88a1ad04a4'::uuid, 'Comparez x² et x³ pour x compris entre 0 et 1.', 'mcq', '["x³ ≤ x²","x³ ≥ x²","Ils sont égaux","On ne peut pas comparer"]'::jsonb, 0, 'Élever à une puissance plus grande rapproche de 0.', 5),
    ('c146bfbd-2a56-5ebe-ad6d-03305dec5642'::uuid, 'cae8560d-01d4-51fd-918e-ec88a1ad04a4'::uuid, 'Pour x supérieur à 1, x³ est plus grand que x².', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'L’ordre s’inverse en 1.', 6),
    ('67c5872a-a6b8-5f5f-ac44-1d60eca3c2ef'::uuid, 'cae8560d-01d4-51fd-918e-ec88a1ad04a4'::uuid, 'La fonction cube admet-elle un minimum ?', 'mcq', '["Non, elle est croissante sur ℝ sans borne","Oui, en 0","Oui, en −1","Oui, elle vaut 0"]'::jsonb, 0, 'Elle prend toutes les valeurs réelles.', 7),
    ('8a86f4ed-02d0-59c9-9dab-e7c789e19325'::uuid, 'cae8560d-01d4-51fd-918e-ec88a1ad04a4'::uuid, 'Si a < b, que peut-on dire de a³ et b³ ?', 'mcq', '["a³ < b³","a³ > b³","a³ = b³","Cela dépend des signes"]'::jsonb, 0, 'Contrairement au carré, le cube conserve l’ordre.', 8),
    ('8a511577-9064-5e34-b062-c9fc85c8ca22'::uuid, 'fac89da2-6bb3-5e98-869e-c883ea39ad1d'::uuid, 'Quel est l’ensemble de définition de la fonction racine carrée ?', 'mcq', '["[0 ; +∞[","ℝ","]0 ; +∞[","]−∞ ; 0]"]'::jsonb, 0, 'La racine d’un négatif n’existe pas dans ℝ.', 1),
    ('93f560ff-09de-5db3-a387-885b4dabe2cc'::uuid, 'fac89da2-6bb3-5e98-869e-c883ea39ad1d'::uuid, 'Comment varie la fonction racine carrée ?', 'mcq', '["Elle est croissante sur tout son ensemble de définition","Elle est décroissante","Elle décroît puis croît","Elle est constante"]'::jsonb, 0, 'Son minimum vaut 0, atteint en 0.', 2),
    ('d346327f-46c5-52de-8f68-4421b0961ca2'::uuid, 'fac89da2-6bb3-5e98-869e-c883ea39ad1d'::uuid, 'Que vaut √(x²) pour un réel x quelconque ?', 'mcq', '["|x|","x","x²","−x"]'::jsonb, 0, 'La racine carrée est toujours positive.', 3),
    ('e6b45a61-2eb6-588b-a901-1273345c2f15'::uuid, 'fac89da2-6bb3-5e98-869e-c883ea39ad1d'::uuid, 'Comparez √x et x pour x compris entre 0 et 1.', 'mcq', '["x ≤ √x","x ≥ √x","Ils sont égaux","On ne peut pas comparer"]'::jsonb, 0, 'Par exemple √0,25 = 0,5.', 4),
    ('935db0c7-851f-53a6-b0a6-73236d502b37'::uuid, 'fac89da2-6bb3-5e98-869e-c883ea39ad1d'::uuid, 'Quelle est la solution de √x = 5 ?', 'mcq', '["x = 25","x = 5","x = √5","Aucune solution"]'::jsonb, 0, 'On élève au carré.', 5),
    ('cf77c5ba-45a0-548f-9643-78cf83f6a298'::uuid, 'fac89da2-6bb3-5e98-869e-c883ea39ad1d'::uuid, 'Les courbes des fonctions carré et racine carrée sont symétriques par rapport à la droite y = x sur les positifs.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Les deux fonctions se défont l’une l’autre sur [0 ; +∞[.', 6),
    ('a69d5c1c-d4c7-506c-938c-0620494c7acc'::uuid, 'fac89da2-6bb3-5e98-869e-c883ea39ad1d'::uuid, 'Pourquoi faut-il vérifier les solutions après avoir élevé au carré ?', 'mcq', '["Parce que cette opération peut créer des solutions parasites","Parce que le calcul est trop long","Parce que la racine change de signe","Parce que l’équation change de degré"]'::jsonb, 0, 'Élever au carré n’est pas une opération réversible sur ℝ.', 7),
    ('5f30dcc1-d187-55cf-9334-da7f1337afa2'::uuid, 'fac89da2-6bb3-5e98-869e-c883ea39ad1d'::uuid, 'L’équation √x = −3 admet-elle une solution ?', 'mcq', '["Non, une racine carrée est toujours positive","Oui, x = 9","Oui, x = −9","Oui, x = 3"]'::jsonb, 0, 'Aucun réel positif n’a une racine négative.', 8),
    ('b0058bcc-4866-54f3-9e1c-3bfc1342c422'::uuid, '4cc06f21-afa6-57cb-a56b-884e1bd7bbf8'::uuid, 'Quel est l’ensemble de définition de la fonction inverse ?', 'mcq', '["ℝ privé de 0","ℝ","[0 ; +∞[","]0 ; +∞["]'::jsonb, 0, 'Diviser par zéro n’a pas de sens.', 1),
    ('65440293-8450-51a3-b8b6-c6be60986285'::uuid, '4cc06f21-afa6-57cb-a56b-884e1bd7bbf8'::uuid, 'Comment varie la fonction inverse ?', 'mcq', '["Elle est décroissante sur chacun des deux intervalles séparément","Elle est décroissante sur ℝ privé de 0","Elle est croissante sur ℝ","Elle croît puis décroît"]'::jsonb, 0, 'On n’énonce jamais de variation sur une réunion d’intervalles.', 2),
    ('19597458-2648-50af-b44b-abe265c1dedc'::uuid, '4cc06f21-afa6-57cb-a56b-884e1bd7bbf8'::uuid, 'Comment s’appelle la courbe de la fonction inverse ?', 'mcq', '["Une hyperbole","Une parabole","Une droite","Une sinusoïde"]'::jsonb, 0, 'Elle est formée de deux branches.', 3),
    ('4950b10f-8b63-5c01-a31d-0f77635b5e05'::uuid, '4cc06f21-afa6-57cb-a56b-884e1bd7bbf8'::uuid, 'La fonction inverse est impaire. Quelle en est la conséquence ?', 'mcq', '["Sa courbe est symétrique par rapport à l’origine","Sa courbe est symétrique par rapport à l’axe des ordonnées","Elle est croissante","Elle est positive"]'::jsonb, 0, 'Car 1/(−x) = −1/x.', 4),
    ('ba4b914e-e904-5ee9-b093-722cf3f0129c'::uuid, '4cc06f21-afa6-57cb-a56b-884e1bd7bbf8'::uuid, 'Que devient 1/x quand x devient très grand ?', 'mcq', '["Il se rapproche de 0 sans l’atteindre","Il devient très grand","Il devient négatif","Il vaut 1"]'::jsonb, 0, 'L’axe des abscisses est une asymptote.', 5),
    ('cd45fd40-5161-5cea-9a94-6a2f33d826ca'::uuid, '4cc06f21-afa6-57cb-a56b-884e1bd7bbf8'::uuid, 'Le signe de 1/x est celui de x.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Négatif avant 0, positif après.', 6),
    ('4564bf89-f61f-5774-a2f2-0854bf1c82dc'::uuid, '4cc06f21-afa6-57cb-a56b-884e1bd7bbf8'::uuid, 'Quelle est la solution de 1/x = 4 ?', 'mcq', '["x = 0,25","x = 4","x = −4","Aucune solution"]'::jsonb, 0, 'x = 1/k.', 7),
    ('c9080f8d-03d8-5545-a2de-f21b7c7a578c'::uuid, '4cc06f21-afa6-57cb-a56b-884e1bd7bbf8'::uuid, 'Peut-on multiplier les deux membres de 1/x ≤ 2 par x ?', 'mcq', '["Non, pas sans connaître le signe de x","Oui, toujours","Oui, si x est non nul","Oui, en inversant le sens"]'::jsonb, 0, 'Il faut passer par un tableau de signes.', 8),
    ('8d45b289-a83a-595b-b76d-f260685322b4'::uuid, '7031a9bb-ebec-5a08-91aa-63db54a8e272'::uuid, 'Comment calcule-t-on t % d’une quantité ?', 'mcq', '["En la multipliant par t/100","En la divisant par t","En lui ajoutant t","En la multipliant par t"]'::jsonb, 0, 'Un pourcentage est une proportion multipliée par 100.', 1),
    ('ca4928cc-c333-55cd-a9d7-e0605d2202b1'::uuid, '7031a9bb-ebec-5a08-91aa-63db54a8e272'::uuid, 'Par quel coefficient multiplie-t-on pour une hausse de 15 % ?', 'mcq', '["1,15","0,85","15","1,015"]'::jsonb, 0, '1 + 15/100.', 2),
    ('383dfa21-e3f2-545a-b0a1-cfd2054e592f'::uuid, '7031a9bb-ebec-5a08-91aa-63db54a8e272'::uuid, 'Par quel coefficient multiplie-t-on pour une baisse de 30 % ?', 'mcq', '["0,70","1,30","0,30","−0,30"]'::jsonb, 0, '1 − 30/100.', 3),
    ('6463e2e2-4917-5038-b3c3-7ca5de3213b0'::uuid, '7031a9bb-ebec-5a08-91aa-63db54a8e272'::uuid, 'Une hausse de 20 % suivie d’une baisse de 20 % ramène-t-elle au point de départ ?', 'mcq', '["Non, il reste une baisse de 4 %","Oui","Non, il reste une hausse de 4 %","Cela dépend de la valeur initiale"]'::jsonb, 0, '1,20 × 0,80 = 0,96.', 4),
    ('11aecfd4-5fbf-5c67-b6d3-db7ffc890a02'::uuid, '7031a9bb-ebec-5a08-91aa-63db54a8e272'::uuid, 'Comment obtient-on le coefficient d’une évolution réciproque ?', 'mcq', '["En prenant l’inverse du coefficient","En changeant le signe du pourcentage","En soustrayant le coefficient de 2","En le divisant par 100"]'::jsonb, 0, 'Après +25 %, il faut −20 % pour revenir au départ.', 5),
    ('5f5a209e-a844-5ea1-8b11-a8b5ab51eb2e'::uuid, '7031a9bb-ebec-5a08-91aa-63db54a8e272'::uuid, 'Passer de 10 % à 12 % est une hausse de 2 points et de 20 %.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Confondre points et pourcentages est l’erreur la plus répandue.', 6),
    ('666aa885-b44d-55e3-98b2-fe80e144347f'::uuid, '7031a9bb-ebec-5a08-91aa-63db54a8e272'::uuid, '40 % des élèves sont en seconde, et 25 % d’entre eux font de l’allemand. Quelle proportion de l’ensemble cela représente-t-il ?', 'mcq', '["10 %","65 %","15 %","25 %"]'::jsonb, 0, 'On multiplie les proportions : 0,40 × 0,25.', 7),
    ('d86cfdaa-65e5-59ac-865c-74fcfd45095e'::uuid, '7031a9bb-ebec-5a08-91aa-63db54a8e272'::uuid, 'Comment calcule-t-on le coefficient de deux évolutions successives ?', 'mcq', '["En multipliant les deux coefficients","En additionnant les pourcentages","En prenant la moyenne","En soustrayant les pourcentages"]'::jsonb, 0, 'Les pourcentages ne s’additionnent pas.', 8),
    ('47b2b27e-ccd4-5aad-8db9-c8d632ef59d1'::uuid, '79e5fd94-f091-5010-b25a-6b65bf8b1813'::uuid, 'Que partage la médiane ?', 'mcq', '["La série ordonnée en deux moitiés de même effectif","La série en quatre groupes égaux","La somme des valeurs","L’étendue en deux"]'::jsonb, 0, 'Elle est peu sensible aux valeurs extrêmes.', 1),
    ('ef1cad29-d3c2-5603-bcf4-b62a431ad06a'::uuid, '79e5fd94-f091-5010-b25a-6b65bf8b1813'::uuid, 'Pourquoi publie-t-on souvent le salaire médian plutôt que le salaire moyen ?', 'mcq', '["Parce que la moyenne est tirée vers le haut par les très hauts salaires","Parce qu’il est plus facile à calculer","Parce que la médiane est toujours plus grande","Parce que la moyenne est interdite"]'::jsonb, 0, 'La médiane résiste aux valeurs extrêmes.', 2),
    ('c253e930-e0fd-53a7-89db-638ad349880c'::uuid, '79e5fd94-f091-5010-b25a-6b65bf8b1813'::uuid, 'Qu’est-ce que l’écart interquartile ?', 'mcq', '["La différence Q3 − Q1","La différence entre le maximum et le minimum","L’écart à la moyenne","La moitié de l’étendue"]'::jsonb, 0, 'Il mesure la dispersion du cœur de la série.', 3),
    ('c4b27501-3bb4-5adf-ac78-af30bdc52704'::uuid, '79e5fd94-f091-5010-b25a-6b65bf8b1813'::uuid, 'Que mesure l’écart type ?', 'mcq', '["La dispersion des valeurs autour de la moyenne","La valeur centrale","L’étendue de la série","Le nombre de valeurs"]'::jsonb, 0, 'Plus il est grand, plus les valeurs sont dispersées.', 4),
    ('bfba6ea1-4c00-520f-91e9-90ad1aba5212'::uuid, '79e5fd94-f091-5010-b25a-6b65bf8b1813'::uuid, 'Que représente Q1 ?', 'mcq', '["La valeur telle qu’au moins un quart des données lui sont inférieures ou égales","La plus petite valeur","La moyenne du premier quart","La médiane de la série"]'::jsonb, 0, 'Q1, médiane et Q3 découpent la série en quatre.', 5),
    ('0ca290a6-87cf-571f-8078-a3430fed9b71'::uuid, '79e5fd94-f091-5010-b25a-6b65bf8b1813'::uuid, 'Deux séries de même moyenne peuvent être très différentes.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'La dispersion peut être radicalement différente.', 6),
    ('fda3db5a-3146-5436-ae6b-be81126a1c34'::uuid, '79e5fd94-f091-5010-b25a-6b65bf8b1813'::uuid, 'Quel graphique résume minimum, quartiles, médiane et maximum ?', 'mcq', '["Le diagramme en boîte","L’histogramme","Le diagramme circulaire","La courbe des fréquences cumulées"]'::jsonb, 0, 'Il permet de comparer plusieurs séries d’un coup d’œil.', 7),
    ('3313905a-1372-5870-a948-258e7cadac15'::uuid, '79e5fd94-f091-5010-b25a-6b65bf8b1813'::uuid, 'Quel procédé graphique exagère visuellement une variation ?', 'mcq', '["Un axe des ordonnées tronqué","Un axe gradué de 0 à 100","Un diagramme en boîte","Un effectif élevé"]'::jsonb, 0, 'La lecture critique commence par l’examen des échelles.', 8),
    ('0e5aff1e-b376-5602-b8f1-f479cfe65335'::uuid, 'fd5871b5-b6a9-5b07-bdb8-29174cbcf828'::uuid, 'Qu’est-ce que l’univers d’une expérience aléatoire ?', 'mcq', '["L’ensemble de toutes les issues possibles","L’ensemble des événements favorables","La probabilité totale","Le nombre d’expériences réalisées"]'::jsonb, 0, 'On le note souvent Ω.', 1),
    ('fa3a00ae-fce5-5855-b6b1-995806f2011d'::uuid, 'fd5871b5-b6a9-5b07-bdb8-29174cbcf828'::uuid, 'Entre quelles valeurs une probabilité est-elle comprise ?', 'mcq', '["Entre 0 et 1","Entre −1 et 1","Entre 0 et 100","Entre 1 et 10"]'::jsonb, 0, 'Toute autre valeur signale une erreur de calcul.', 2),
    ('d837077d-07b7-5f82-b39c-02c60bb3e4cd'::uuid, 'fd5871b5-b6a9-5b07-bdb8-29174cbcf828'::uuid, 'Comment calcule-t-on P(A) en situation d’équiprobabilité ?', 'mcq', '["Nombre d’issues favorables divisé par nombre d’issues possibles","Somme des issues favorables","Nombre d’issues possibles divisé par les favorables","1 divisé par le nombre d’événements"]'::jsonb, 0, 'À condition que toutes les issues soient également probables.', 3),
    ('98cf1aba-b7c9-51c8-8d02-0ed1a5b07cde'::uuid, 'fd5871b5-b6a9-5b07-bdb8-29174cbcf828'::uuid, 'Que vaut la probabilité de l’événement contraire de A ?', 'mcq', '["1 − P(A)","P(A) − 1","1/P(A)","−P(A)"]'::jsonb, 0, 'Très utile pour les événements du type au moins un.', 4),
    ('7912ff72-1fcd-598f-b626-ed5410d08b49'::uuid, 'fd5871b5-b6a9-5b07-bdb8-29174cbcf828'::uuid, 'Que vaut P(A ∪ B) ?', 'mcq', '["P(A) + P(B) − P(A ∩ B)","P(A) + P(B)","P(A) × P(B)","P(A) − P(B)"]'::jsonb, 0, 'On retranche l’intersection comptée deux fois.', 5),
    ('f3c20c94-ff5b-5be9-918c-aea7e42b5850'::uuid, 'fd5871b5-b6a9-5b07-bdb8-29174cbcf828'::uuid, 'Deux événements incompatibles ne peuvent pas se produire en même temps.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Leur intersection est vide, donc P(A ∪ B) = P(A) + P(B).', 6),
    ('c1667d2c-689e-5049-9ece-239682132824'::uuid, 'fd5871b5-b6a9-5b07-bdb8-29174cbcf828'::uuid, 'Sur un arbre de probabilités, que fait-on le long d’un chemin ?', 'mcq', '["On multiplie les probabilités","On les additionne","On les soustrait","On prend la plus grande"]'::jsonb, 0, 'On additionne ensuite les chemins qui réalisent l’événement.', 7),
    ('6f4448bf-af3b-53f5-81b1-1b2de45703ce'::uuid, 'fd5871b5-b6a9-5b07-bdb8-29174cbcf828'::uuid, 'Quelle est la probabilité d’obtenir un nombre pair avec un dé équilibré à six faces ?', 'mcq', '["1/2","1/3","1/6","2/3"]'::jsonb, 0, 'Trois issues favorables sur six.', 8),
    ('d403b466-85bc-54a0-b6bb-d5b6650389a1'::uuid, '0a0d5e6c-e7b0-508f-a5fe-da8747be970d'::uuid, 'Qu’est-ce qu’un échantillon de taille n ?', 'mcq', '["Le résultat de n répétitions indépendantes de la même expérience","Les n premiers individus d’une liste","Une population de taille n","Un tirage sans remise de n éléments"]'::jsonb, 0, 'L’indépendance des tirages est essentielle.', 1),
    ('ea34ea05-e519-5600-923e-2ad0dff39cc4'::uuid, '0a0d5e6c-e7b0-508f-a5fe-da8747be970d'::uuid, 'Qu’est-ce que la fluctuation d’échantillonnage ?', 'mcq', '["La variation de la fréquence observée d’un échantillon à l’autre","Une erreur de mesure","Un biais de recrutement","Une variation de la population"]'::jsonb, 0, 'Elle est inhérente au tirage aléatoire.', 2),
    ('9a1be51f-4bf9-5228-949f-c3bad9885200'::uuid, '0a0d5e6c-e7b0-508f-a5fe-da8747be970d'::uuid, 'Que devient la fluctuation quand la taille de l’échantillon augmente ?', 'mcq', '["Elle diminue","Elle augmente","Elle reste constante","Elle devient nulle"]'::jsonb, 0, 'La précision croît comme la racine de n.', 3),
    ('7a9cc32d-5ba0-57bb-bbe6-257240470c2c'::uuid, '0a0d5e6c-e7b0-508f-a5fe-da8747be970d'::uuid, 'Quel est l’intervalle de fluctuation au seuil de 95 % pour une proportion p ?', 'mcq', '["[p − 1/√n ; p + 1/√n]","[p − 1/n ; p + 1/n]","[p − √n ; p + √n]","[p − 0,05 ; p + 0,05]"]'::jsonb, 0, 'Valable pour n assez grand et p pas trop extrême.', 4),
    ('2c340958-e31e-5a2d-aaa6-9df04548507e'::uuid, '0a0d5e6c-e7b0-508f-a5fe-da8747be970d'::uuid, 'Par combien faut-il multiplier n pour diviser l’incertitude par deux ?', 'mcq', '["Par quatre","Par deux","Par huit","Par seize"]'::jsonb, 0, 'Parce que la largeur est en 1/√n.', 5),
    ('b871662e-63f0-5c45-8ff1-5e1015272a46'::uuid, '0a0d5e6c-e7b0-508f-a5fe-da8747be970d'::uuid, 'Une fréquence observée hors de l’intervalle de fluctuation conduit à rejeter l’hypothèse au seuil de 95 %.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Rester dedans ne démontre pas l’hypothèse pour autant.', 6),
    ('a1632e75-fd61-5e33-9725-0fc4087518cf'::uuid, '0a0d5e6c-e7b0-508f-a5fe-da8747be970d'::uuid, 'Un échantillon très grand mais mal recruté est-il fiable ?', 'mcq', '["Non, un biais de recrutement ne se corrige pas par la taille","Oui, la taille compense tout","Oui, au-delà de 10 000 individus","Cela dépend de la population"]'::jsonb, 0, 'La représentativité prime sur la taille.', 7),
    ('43d045b6-14db-566c-b01a-264b20ce898b'::uuid, '0a0d5e6c-e7b0-508f-a5fe-da8747be970d'::uuid, 'Quel est l’intervalle de fluctuation pour p = 0,5 et n = 100 ?', 'mcq', '["[0,4 ; 0,6]","[0,45 ; 0,55]","[0,3 ; 0,7]","[0,49 ; 0,51]"]'::jsonb, 0, '1/√100 = 0,1.', 8)
  ) AS v(id, quiz_id, question, kind, options, correct_index, explanation, position)
-- Le quiz doit exister : si le NOT EXISTS ci-dessus a écarté un quiz (une
-- leçon en avait déjà un), ses questions ne partent pas dans le vide.
 WHERE EXISTS (SELECT 1 FROM public.quizzes qz WHERE qz.id = v.quiz_id)
ON CONFLICT (id) DO NOTHING;

-- 5. Sonde finale ----------------------------------------------------------
DO $$
DECLARE
  n_vides integer;
  n_chap  integer;
BEGIN
  SELECT count(*) INTO n_chap FROM public.chapters c
   JOIN public.subjects s ON s.id = c.subject_id
   WHERE s.slug IN ('maths');
  SELECT count(*) INTO n_vides FROM public.subjects s
   WHERE s.slug IN ('maths')
     AND NOT EXISTS (SELECT 1 FROM public.chapters c WHERE c.subject_id = s.id);
  IF n_vides > 0 THEN
    RAISE EXCEPTION 'Migration 282 incomplète : % matiere(s) encore sans chapitre', n_vides;
  END IF;
  RAISE NOTICE 'Migration 282 OK : % chapitres sur les matieres visees.', n_chap;
END $$;
